let clrs = ["#3DB2FF", "#FFB830", "#FF2442", "#00F5D4", "#7B2CBF"];

function setup() {
  createCanvas(windowWidth, windowHeight);
  frameRate(30);
  noFill();
}

function draw() {
  let bass = (typeof sub_bass !== 'undefined') ? sub_bass : 0;
  let perc = (typeof percussive !== 'undefined') ? percussive : 0;

  background(18, 18, 28);

  let centerX = width / 2;
  let centerY = height / 2;
  let maxRad = min(width, height) * 0.45;

  strokeWeight(map(perc, 0, 1, 1.5, 3.5));

  for (let i = 0; i < 360; i += 15) {
    let radius = map(i, 0, 360, 20, maxRad) * (1.0 + bass * 0.25);
    let clr = clrs[(int(i / 15)) % clrs.length];
    stroke(clr);

    push();
    translate(centerX, centerY);
    let rot = radians(i) + sin(frameCount * 0.02 + i * 0.05) * 0.5;
    rotate(rot);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.15) {
      let x = cos(a) * radius;
      let y = sin(a) * radius;
      let offset = sin(a * 8 + i * 0.1 + frameCount * 0.05) * (12 + bass * 20);
      vertex(x + offset, y + offset);
    }
    endShape(CLOSE);
    pop();
  }
}
